// Static docs screenshot checker (no dependencies).
//
// `docs/public/screenshots/` is nothing but a Playwright build artifact: every
// image is generated by a demo under `packages/webview/demo/`. `check-docs-links.mjs`
// covers only one half of the pairing (a docs page points at an image that is
// missing, and only as a warning). This script covers the other half, by
// cross-checking the two source lists — no demo run, no generated files:
//
//   orphan  a demo generates `screenshots/X`, but no docs page references it
//   broken  docs reference `screenshots/X`, but no demo generates it
//
// Both lists are read straight from source: the demo helper calls
// (`screenshotWebp` / `elementScreenshotWebp`) mention the target path as a
// string literal, and docs reference images with markdown image syntax or
// `<img src="...">`.
//
// Run: node scripts/check-docs-screenshots.mjs            (orphans are warnings)
//      node scripts/check-docs-screenshots.mjs --strict   (orphans fail — used by
//      CI and pre-commit, so a leftover shot cannot sit unnoticed for a year)

import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, dirname, extname, relative } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const docsDir = join(root, "docs");
const demoDir = join(root, "packages", "webview", "demo");

// A demo leaves `screenshots/<name>.webp` in a string literal it hands to the
// screenshot helper. Match the directory segment rather than the helper names so
// both helpers (page- and element-level) and any future wrapper are covered.
const DEMO_SHOT = /screenshots\/([\w./-]+?\.webp)/g;
// Docs pick images up either as markdown images or as `<figure><img src>`.
const MD_IMAGE = /!\[[^\]]*\]\(([^)\s]+)/g;
const HTML_IMAGE = /<img\b[^>]*\ssrc="([^"]+)"/g;

const strict = process.argv.includes("--strict");

function collectFiles(dir, accept, files = []) {
  for (const entry of readdirSync(dir)) {
    if (entry === "node_modules" || entry === ".vitepress") continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      collectFiles(full, accept, files);
    } else if (accept(full)) {
      files.push(full);
    }
  }
  return files;
}

// `screenshots/foo.webp`, `/screenshots/foo.webp` and `../public/screenshots/foo.webp`
// all name the same artifact; the map key is just `foo.webp`.
function shotName(url) {
  const i = url.indexOf("screenshots/");
  if (i < 0) return null;
  const name = url
    .slice(i + "screenshots/".length)
    .split(/[?#]/)[0]
    .replace(/^\/+/, "");
  return name.endsWith(".webp") ? name : null;
}

const generated = new Map();
for (const file of collectFiles(demoDir, (f) => extname(f) === ".ts")) {
  const content = readFileSync(file, "utf8");
  for (const match of content.matchAll(DEMO_SHOT)) {
    const name = match[1];
    if (!generated.has(name)) generated.set(name, new Set());
    generated.get(name).add(file);
  }
}

const referenced = new Map();
for (const file of collectFiles(docsDir, (f) =>
  [".md", ".vue", ".ts"].includes(extname(f)),
)) {
  const content = readFileSync(file, "utf8");
  for (const regex of [MD_IMAGE, HTML_IMAGE]) {
    for (const match of content.matchAll(regex)) {
      const name = shotName(match[1]);
      if (!name) continue;
      if (!referenced.has(name)) referenced.set(name, new Set());
      referenced.get(name).add(file);
    }
  }
}

const orphans = [...generated.keys()]
  .filter((name) => !referenced.has(name))
  .sort();
const broken = [...referenced.keys()]
  .filter((name) => !generated.has(name))
  .sort();

const warnings = orphans.map((name) => {
  const demos = [...generated.get(name)]
    .map((f) => relative(root, f))
    .join(", ");
  return `screenshots/${name}: generated by ${demos} but referenced by no docs page`;
});
const errors = broken.map((name) => {
  const docs = [...referenced.get(name)]
    .map((f) => relative(root, f))
    .join(", ");
  return `screenshots/${name}: referenced by ${docs} but no demo generates it`;
});

for (const w of warnings) console.log("WARNING: " + w);
for (const e of errors) console.log("ERROR: " + e);

const okCount = [...referenced.keys()].length - broken.length;
const failing = errors.length > 0 || (strict && warnings.length > 0);

console.log("");
console.log(
  `${failing ? "FAIL" : "PASS"}: ${okCount} screenshots referenced and generated, ` +
    `${warnings.length} orphaned${strict ? "" : " (warnings)"}, ` +
    `${errors.length} broken (errors)`,
);

process.exit(failing ? 1 : 0);
